// Copyright (c) 2026 Roshan. All rights reserved.package com.roshan.persona.commonimport timber.log.Timberimport java.util.UUID/** * Correlation ID — uniquely identifies a request as it flows through the system. * * Generated at the entry point (Brain route request), attached to every log, * metric, trace span, and audit-log entry. Allows reconstructing the full * request lifecycle after the fact. * * Wrap in a value class so it's allocation-free at runtime while being * type-safe (cannot be confused with a regular String). * * @sample * ```kotlin * suspend fun route(input: String): Result<String> = withCorrelationId { *     Timber.tag("NOUS.Brain").i("Routing input: $input") *     // ... * } * ``` */@JvmInlinevalue class CorrelationId(val value: String) {    override fun toString(): String = value    companion object {        /** Generate a fresh, random correlation ID. */        fun generate(): CorrelationId = CorrelationId(UUID.randomUUID().toString())        /** Parse an existing correlation ID (e.g., from an incoming deep link). */        fun parse(value: String): CorrelationId =            runCatching { CorrelationId(UUID.fromString(value).toString()) }                .getOrElse { generate() }    }}